def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); labs = sorted(set(feats.stratum))
    S = np.array([[s == l for l in labs[1:]] for s in feats.stratum], float).reshape(n, -1)
    B = np.column_stack([np.ones(n), S])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def ll(cols):
        Z = np.column_stack([B] + cols) if cols else B
        w = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ w, -30, 30); m = 1 / (1 + np.exp(-eta)); W = m * (1 - m) + 1e-9
            H = Z.T @ (Z * W[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - m)); w += step
            if np.max(np.abs(step)) < 1e-7: break
        m = np.clip(1 / (1 + np.exp(-np.clip(Z @ w, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))
    col = lambda j: X[:, j]
    def LL(sel): return ll([col(j) for j in sel])
    sel = []; cur = LL(sel)
    gates = [0.01 / p, 0.05 / p]
    while len(sel) < MAX_DRIVERS:
        a = gates[min(len(sel), len(gates) - 1)]
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            v = LL(sel + [j])
            if best is None or v > best[1]: best = (j, v)
        if best is None or stats.chi2.sf(2 * (best[1] - cur), 1) > a: break
        j, v = best
        clus = [k for k in range(p) if k not in sel and abs(R[j, k]) >= 0.6 and
                not any(abs(R[k, q]) >= 0.6 for q in sel)] + [j]
        clus = list(dict.fromkeys(clus))
        lv = {k: LL(sel + [k]) for k in clus}
        cand = [k for k in clus if lv[k] >= v - 2.0]
        if len(cand) > 1:
            def tot(k):
                return sum(max(0.0, LL(sel + [k, q]) - lv[k]) for q in clus if q != k)
            j = min(cand, key=tot); v = lv[j]
        sel.append(j); cur = v
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (cur - LL(rest)), 1) > 0.05 / p:
                sel = rest; cur = LL(sel); changed = True; break
    base = [col(j) for j in sel]; b0 = ll(base)
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    P = np.column_stack([X[:, a] * X[:, b] for a, b in pairs]); P = (P - P.mean(0)) / (P.std(0) + 1e-9)
    r0 = y - y.mean(); sc = (P.T @ r0) ** 2 / (np.sum(P ** 2, 0) * y.mean() * (1 - y.mean()) + 1e-9)
    prods = []; npair = len(pairs)
    for i in np.argsort(-sc)[:20]:
        a, b = pairs[i]
        mains = [col(k) for k in dict.fromkeys([a, b]) if k not in sel]
        l1 = ll(base + mains); l2 = ll(base + mains + [X[:, a] * X[:, b]])
        if stats.chi2.sf(2 * (l2 - l1), 1) < 0.01 / npair:
            if any(abs(R[a, c]) >= 0.6 or abs(R[b, c]) >= 0.6 for pr in prods for c in pr): continue
            prods.append((a, b))
        if len(prods) >= 2: break
    drivers = [ids[j] for j in sel]
    for a, b in prods:
        for k in (a, b):
            if ids[k] not in drivers: drivers.append(ids[k])
    drivers = tuple(drivers[:MAX_DRIVERS])
    cols = tuple(dict.fromkeys([ids[j] for j in sel] + [ids[k] for pr in prods for k in pr]))
    return Design(drivers=drivers, columns=cols, products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

